/* ============================================================
   VENDHAN CRACKERS — Pricing Calculator
   ============================================================ */

/**
 * Calculate order pricing from cart items and shop settings.
 *
 * @param {Array} items - [{ price, quantity }]
 * @param {Object} settings - { deliveryCharge, freeDeliveryThreshold, gstPercent }
 * @param {Object} options - { comboDiscount, discountAmount, couponDiscount }
 *   - comboDiscount: discount generated by combo pricing
 *   - discountAmount: legacy alias for comboDiscount (backward compatible)
 *   - couponDiscount: coupon discount (defaults to 0; the coupon system computes
 *     it in couponService and passes it here so this stays the SINGLE pricing
 *     math point — the same discount is never applied twice).
 * @returns {Object} { subtotal, comboDiscount, couponDiscount, discount, deliveryCharge, gst, total }
 */
function calculatePricing(items, settings, options = {}) {
  // 1. Subtotal = Σ(price × quantity)
  const subtotal = items.reduce((sum, item) => sum + (item.price * item.quantity), 0);

  // 2. Discounts — combo discount is the only product-level discount applied.
  //    Legacy `discountAmount` is treated as comboDiscount for backward compatibility.
  //    `couponDiscount` is 0 unless provided (coupon restored in Phase 6).
  const comboDiscount = options.comboDiscount !== undefined
    ? (options.comboDiscount || 0)
    : (options.discountAmount || 0);
  const couponDiscount = options.couponDiscount !== undefined
    ? (options.couponDiscount || 0)
    : 0;

  // Total discount = combo discount only
  const discount = comboDiscount + couponDiscount;

  // 3. Delivery charge — free above threshold
  const freeThreshold = settings.freeDeliveryThreshold || 1000;
  const deliveryCharge = subtotal >= freeThreshold ? 0 : (settings.deliveryCharge || 0);

  // 4. GST — Products are already "inclusive of all taxes", so GST must NOT be
  //    calculated and added again. Keep the field as 0 for backward compatibility
  //    with existing reports/aggregations that subtract pricing.gst.
  const gst = 0;

  // 5. Grand total (subtotal − discount + delivery). No separate GST is added.
  const total = Math.round((subtotal - discount + deliveryCharge) * 100) / 100;

  return {
    subtotal: Math.round(subtotal * 100) / 100,
    comboDiscount: Math.round(comboDiscount * 100) / 100,
    couponDiscount: Math.round(couponDiscount * 100) / 100,
    discount: Math.round(discount * 100) / 100,
    deliveryCharge,
    gst,
    total
  };
}

module.exports = calculatePricing;